css:
.rm-t-navy-classic{padding:0 0 46px;background:#ffffff;color:#233043;font-size:13px;line-height:1.64;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei","Noto Sans SC",sans-serif;}
.rm-t-navy-classic .rm-head{margin:0;padding:34px 46px 26px;background:linear-gradient(135deg,#1b3557 0%,#152846 58%,#1f3f68 100%);border-bottom:2px solid #b79355;color:#f2f6fb;}
.rm-t-navy-classic .rm-name{margin:0;font-family:Georgia,"Songti SC","Noto Serif SC",serif;font-size:31px;line-height:1.2;font-weight:600;letter-spacing:.12em;color:#ffffff;}
.rm-t-navy-classic .rm-role{margin:8px 0 0;font-size:12px;letter-spacing:.2em;color:#b9cbe4;}
.rm-t-navy-classic .rm-contact{grid-template-columns:repeat(2,minmax(0,1fr));gap:7px 30px;margin:19px 0 0;max-width:566px;}
.rm-t-navy-classic .rm-c{align-items:baseline;gap:8px;}
.rm-t-navy-classic .rm-k{font-size:9.5px;letter-spacing:.16em;color:#93aacd;}
.rm-t-navy-classic .rm-v{font-size:12px;color:#e8eef7;}
.rm-t-navy-classic .rm-photo{width:92px;height:92px;background:#dfe7f2;border:2px solid rgba(255,255,255,.32);}
.rm-t-navy-classic .rm-body{padding:0 46px;}
.rm-t-navy-classic .rm-sec{margin-top:23px;}
.rm-t-navy-classic .rm-sec-h{display:flex;align-items:center;gap:9px;margin:0 0 10px;padding-bottom:5px;border-bottom:1px solid #ccd7e6;}
.rm-t-navy-classic .rm-sec-h::before{content:"";flex:0 0 auto;width:14px;height:2px;background:#1b3557;}
.rm-t-navy-classic .rm-sec-t{font-size:12.5px;font-weight:700;letter-spacing:.2em;color:#1b3557;}
.rm-t-navy-classic .rm-summary{font-size:12.8px;line-height:1.74;color:#3c4a5c;}
.rm-t-navy-classic .rm-item{margin:0 0 11px;}
.rm-t-navy-classic .rm-item-t{font-weight:650;color:#16273f;}
.rm-t-navy-classic .rm-item-role{margin-left:7px;font-size:12.2px;color:#5b6b80;}
.rm-t-navy-classic .rm-date{font-size:11px;color:#7285a0;font-variant-numeric:tabular-nums;}
.rm-t-navy-classic .rm-item-sub{margin-top:2px;font-size:11.5px;color:#6d7d92;}
.rm-t-navy-classic .rm-bullets{margin:5px 0 0;padding-left:15px;}
.rm-t-navy-classic .rm-bullets li{margin:3px 0;color:#39465a;}
.rm-t-navy-classic .rm-bullets li::marker{color:#1b3557;}
.rm-t-navy-classic .rm-sec-campus .rm-item-t{color:#1b3557;}
.rm-t-navy-classic .rm-sec-hobbies .rm-tags{gap:6px;}
.rm-t-navy-classic .rm-sec-hobbies .rm-tag{background:#ffffff;}
.rm-t-navy-classic .rm-edu-courses{margin-top:3px;font-size:11.5px;color:#6d7d92;}
.rm-t-navy-classic .rm-edu-courses .rm-k{margin-right:7px;color:#8a9bb4;}
.rm-t-navy-classic .rm-skill-row{grid-template-columns:100px minmax(0,1fr);gap:10px;margin:0 0 7px;}
.rm-t-navy-classic .rm-skill-k{font-size:12px;font-weight:600;color:#1b3557;}
.rm-t-navy-classic .rm-tags{gap:5px;}
.rm-t-navy-classic .rm-tag{padding:1px 9px;border:1px solid #d3dde9;border-radius:2px;background:#f5f8fc;color:#2b4a72;font-size:11px;line-height:1.7;}
.rm-t-navy-classic .rm-award-row{margin:0 0 7px;align-items:baseline;}
.rm-t-navy-classic .rm-award-t{font-weight:600;color:#16273f;}
.rm-t-navy-classic .rm-award-desc{font-size:11.5px;color:#6d7d92;}
.rm-t-navy-classic strong{color:#0f2038;}
